WITH scored AS (SELECT *, PERCENT_RANK() OVER w_recent AS price_percent_rank, ROW_NUMBER() OVER (PARTITION BY category ORDER BY price, id) AS event_seq, FIRST_VALUE(price, TRUE) OVER (ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_price, SUM(stock_qty) OVER (ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_stock_qty, MAX(price) OVER (PARTITION BY MONTH(launch_date), brand) AS launch_date_month_max_price FROM products WINDOW w_recent AS (PARTITION BY supplier_id, category ORDER BY price NULLS FIRST)), with_windows AS (SELECT *, AVG(event_seq) OVER (PARTITION BY brand, supplier_id ORDER BY running_stock_qty, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS event_seq_avg_3_prior, SUM(event_seq) OVER (PARTITION BY supplier_id, category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_event_seq, NTILE(3) OVER (PARTITION BY supplier_id ORDER BY first_known_price, id) AS first_known_price_bucket FROM scored), enriched AS (SELECT e.id, e.category, e.price, e.cost, e.stock_qty, e.launch_date, e.supplier_id, e.price_percent_rank, e.event_seq, e.event_seq_avg_3_prior, e.running_event_seq, e.first_known_price_bucket, b.country, b.rating, b.city FROM with_windows e LEFT JOIN suppliers b ON e.supplier_id <=> b.id WHERE LENGTH(b.supplier_name) < 10), with_dims AS (SELECT a.id, a.category, a.stock_qty, a.launch_date, a.supplier_id, a.running_event_seq, a.rating, d.country AS supplier_country, d.rating AS supplier_rating, d.supplier_name FROM enriched a LEFT JOIN suppliers d ON a.supplier_id <=> d.id), latest_match AS (SELECT s.id, s.stock_qty, s.launch_date, s.rating, s.supplier_country, s.supplier_name, latest.order_item_unit_price FROM with_dims s LEFT JOIN LATERAL (SELECT c.unit_price AS order_item_unit_price FROM order_items c WHERE c.product_id = s.id ORDER BY c.unit_price DESC, c.id DESC LIMIT 1) latest ON TRUE), latest_match_products AS (SELECT s.*, x.store_sale_sale_date, x.store_sale_units FROM latest_match s JOIN LATERAL (SELECT c.sale_date AS store_sale_sale_date, c.units AS store_sale_units FROM store_sales c WHERE c.product_id = s.id ORDER BY c.revenue DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, stock_qty, launch_date, rating, supplier_country, supplier_name, order_item_unit_price, store_sale_sale_date, store_sale_units FROM latest_match_products;
